sp_widget.client_script:
api.controller=function($scope, $uibModalInstance) { // <-- $uibModalInstance é crucial para modais
    var c = this;

    // Recebe os filtros passados pelo widget pai (widgetInput no $spModal.open)
    if ($scope.properties.widgetInput.filters) {
        c.data = angular.copy($scope.properties.widgetInput.filters);
    } else {
        c.data = {};
    }

    // Função que retorna os dados filtrados para o widget pai e fecha o modal
    c.applyFilters = function() {
        $uibModalInstance.close(c.data); // Retorna c.data para o .then() do widget pai
    };

    // Função para limpar os filtros
    c.clearFilters = function() {
        c.data = {}; // Limpa o modelo de dados
    };

    // Configura o botão de fechar (X)
    c.cancel = function() {
        $uibModalInstance.dismiss('cancel');
    };
}

